import heapq

def solve(grid, start, goal):
    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'  # Check if cell is free

    # A* search using Manhattan distance as heuristic
    def manhattan_distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    # Priority queue: (cost, current position, path)
    priority_queue = [(manhattan_distance(start, goal), 0, start, [start])]
    visited = set()

    while priority_queue:
        _, cost, current, path = heapq.heappop(priority_queue)

        if current == goal:
            return path

        if current in visited:
            continue

        visited.add(current)

        row, col = current
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if is_valid(new_row, new_col):
                new_cost = cost + 1
                new_path = path + [(new_row, new_col)]
                heapq.heappush(priority_queue, (new_cost + manhattan_distance((new_row, new_col), goal), new_cost, (new_row, new_col), new_path))

    return []  # No path found
