                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == '.':
                    visited[nr][nc] = True
                    queue.append((nr, nc, path + [(nr, nc)]))
        return []

    # Try BFS with increasing step budget
    # If BFS fails, try a DFS with increasing budget
    def dfs_budgeted(r, c, path, max_steps):
        if (r, c) == goal:
            return path
        if len(path) > max_steps:
            return None
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in path:
                result = dfs_budgeted(nr, nc, path + [(nr, nc)], max_steps)
                if result:
                    return result
        return None

    # Try BFS first
    path = bfs()
    if path:
        return path

    # If BFS failed, try increasing step DFS
    max_steps = 1
    while True:
        path = dfs_budgeted(start[0], start[1], [start], max_steps)
        if path:
