        forward_visited = set()
        forward_queue = deque([(start[0], start[1], [start])])
        forward_visited.add((start[0], start[1]))

        backward_visited = set()
        backward_queue = deque([(goal[0], goal[1], [goal])])
        backward_visited.add((goal[0], goal[1]))

        while forward_queue and backward_queue:
            # Expand forward
            r, c, path = forward_queue.popleft()
            if (r, c) in backward_visited:
                return path + list(reversed(backward_visited[(r, c)]))
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in forward_visited:
                    forward_visited.add((nr, nc))
                    forward_queue.append((nr, nc, path + [(nr, nc)]))

            # Expand backward
            r, c, path = backward_queue.popleft()
            if (r, c) in forward_visited:
                return path + list(reversed(forward_visited[(r, c)]))
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
