from collections import deque

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # BFS from start and from goal
    start_frontier = deque([(start[0], start[1], None)])
    goal_frontier = deque([(goal[0], goal[1], None)])
    start_visited = {(start[0], start[1]): start}
    goal_visited = {(goal[0], goal[1]): goal}

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while start_frontier and goal_frontier:
        # Expand start frontier
        for _ in range(len(start_frontier)):
            r, c, prev = start_frontier.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in start_visited:
                    start_visited[(nr, nc)] = (r, c)
                    start_frontier.append((nr, nc, (r, c)))

        # Expand goal frontier
        for _ in range(len(goal_frontier)):
            r, c, prev = goal_frontier.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in goal_visited:
                    goal_visited[(nr, nc)] = (r, c)
                    goal_frontier.append((nr, nc, (r, c)))

        # Check for meeting point
        for key in start_visited:
            if key in goal_visited:
                # Reconstruct path from start to goal
                path = []
                current = key
                while current is not None:
                    path.append(current)
                    current = start_visited.get(current, None)
                path.reverse()
                # Check if the path connects to the goal
                if path[-1] == goal:
                    return path
                # If not, reconstruct from goal side
                current = key
                while current is not None:
                    path.append(current)
                    current = goal_visited.get(current, None)
                path.reverse()
                if path[0] == start:
                    return path
                else:
                    return []

    return []
