import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Priority queue: (priority, row, col, path)
    pq = [(manhattan(start, goal), start[0], start[1], [start])]

    # Visited set: (row, col) -> steps_so_far
    visited = {}

    while pq:
        priority, r, c, path = heapq.heappop(pq)

        # Check if goal is reached
        if (r, c) == goal:
            return path

        # Skip if already visited with a lower or equal cost
        if (r, c) in visited and visited[(r, c)] <= priority:
            continue

        visited[(r, c)] = priority

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                new_priority = priority + 1 + manhattan((nr, nc), goal)
                new_path = path + [(nr, nc)]
                heapq.heappush(pq, (new_priority, nr, nc, new_path))

    return []

def manhattan(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])
