    # Check if a cell is valid
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Bidirectional BFS
    def bidirectional_bfs(start, goal):
        start_queue = deque([start])
        goal_queue = deque([goal])

        start_visited = {start: [start]}
        goal_visited = {goal: [goal]}

        # Use BFS from both ends
        while start_queue and goal_queue:
            # Expand from start
            if len(start_queue) <= len(goal_queue):
                current_pos = start_queue.popleft()
                current_path = start_visited[current_pos]

                for dr, dc in directions:
                    r, c = current_pos[0] + dr, current_pos[1] + dc
                    if is_valid(r, c) and (r, c) not in start_visited:
                        new_path = current_path + [(r, c)]
                        start_visited[(r, c)] = new_path
                        start_queue.append((r, c))
                        if (r, c) in goal_visited:
                            return new_path + goal_visited[(r, c)][::-1]
            else:
                current_pos = goal_queue.popleft()
                current_path = goal_visited[current_pos]

                for dr, dc in directions:
                    r, c = current_pos[0] + dr, current_pos[1] + dc
                    if is_valid(r, c) and (r, c) not in goal_visited:
                        new_path = current_path + [(r, c)]
                        goal_visited[(r, c)] = new_path
                        goal_queue.append((r, c))
                        if (r, c) in start_visited:
                            return start_visited[(r, c)] + new_path[::-1]

        return []

    return bidirectional_bfs(start, goal)
