                for dr, dc in directions:
                    r, c = current[0] + dr, current[1] + dc
                    if is_valid(r, c) and (r, c) not in visited_start:
                        if (r, c) in visited_goal:
                            return path + [ (r, c) ] + list(reversed(visited_goal[(r, c)]))
                        visited_start.add((r, c))
                        frontier_start.append(((r, c), path + [(r, c)]))

            # Expand from goal side
            for _ in range(len(frontier_goal)):
                current, path = frontier_goal.popleft()
                for dr, dc in directions:
                    r, c = current[0] + dr, current[1] + dc
                    if is_valid(r, c) and (r, c) not in visited_goal:
                        if (r, c) in visited_start:
                            return path + [ (r, c) ] + list(reversed(visited_start[(r, c)]))
                        visited_goal.add((r, c))
                        frontier_goal.append(((r, c), path + [(r, c)]))

