    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    def heuristic(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    pq = [(0, start)]
    came_from = {}
    cost_so_far = {start: 0}

    while pq:
        _, current = heapq.heappop(pq)
        if current == goal:
            break
        r, c = current
        if grid[r][c] == '#':
            continue
        for dr, dc in dirs:
