    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs(current, depth, path, visited):
        if current == goal:
            return path + [current]
        if depth == 0:
            return None
        visited.add(current)
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                result = dfs((nr, nc), depth - 1, path + [current], visited)
                if result is not None:
                    return result
        visited.remove(current)
        return None

    # Iterative Deepening DFS
    max_depth = rows * cols  # Upper bound on depth
    for depth in range(1, max_depth + 1):
        visited = set()
        result = dfs(start, depth, [], visited)
        if result:
            return result
    return []
