import heapq

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    # Dijkstra's algorithm using a priority queue
    priority_queue = [(0, start)]
    came_from = {}
    cost_so_far = {start: 0}

    while priority_queue:
        current_cost, current = heapq.heappop(priority_queue)

        if current == goal:
            break

        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in cost_so_far:
                new_cost = current_cost + 1
                if (r, c) not in cost_so_far or new_cost < cost_so_far[(r, c)]:
                    cost_so_far[(r, c)] = new_cost
                    heapq.heappush(priority_queue, (new_cost, (r, c)))
                    came_from[(r, c)] = current

    # Reconstruct path
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = came_from.get(current, None)
        if current is None:
            return []
    path.append(start)
    path.reverse()
    return path
