from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Check if a cell is valid (within bounds and not a wall)
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Recursive depth-first search (DFS) to find a path
    def dfs(current, path):
        if current == goal:
            return path + [current]

        r, c = current
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                result = dfs((nr, nc), path + [current])
                if result:
                    return result
        return None

    return dfs(start, [])
