import heapq

def solve(n, edges, s, t):
    from collections import deque

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bidirectional Dijkstra
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        prev = [-1] * n
        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                break
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    prev[v] = u
                    heapq.heappush(heap, (dist[v], v))
        # Reconstruct path if needed, but we just need the distance
        return dist[end], prev

    # Run Dijkstra from both ends
    dist_s_to_t, _ = dijkstra(s, t)
    dist_t_to_s, _ = dijkstra(t, s)

    # If both directions are not reachable, return -1
    if dist_s_to_t == float('inf') and dist_t_to_s == float('inf'):
        return -1
    # If only one direction is reachable, return the reachable distance
    elif dist_s_to_t == float('inf'):
        return dist_t_to_s
    elif dist_t_to_s == float('inf'):
        return dist_s_to_t
    else:
        return min(dist_s_to_t, dist_t_to_s)
