import heapq

def solve(n, edges, s, t):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm from source to target
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                return d
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return -1

    # Bidirectional Dijkstra's algorithm
    def bidirectional_dijkstra(start, end):
        # Forward search from start
        forward_dist = [float('inf')] * n
        forward_dist[start] = 0
        forward_heap = [(0, start)]
        # Reverse search from end (considering reversed edges)
        reverse_dist = [float('inf')] * n
        reverse_dist[end] = 0
        reverse_heap = [(0, end)]
        # Keep track of visited nodes
        visited = [False] * n
        # Keep track of the best meeting point
        best = float('inf')

        while forward_heap and reverse_heap:
            # Expand forward search
            while forward_heap:
                d, u = heapq.heappop(forward_heap)
                if visited[u]:
                    continue
                visited[u] = True
                for v, w in adj[u]:
                    if forward_dist[v] > d + w:
                        forward_dist[v] = d + w
                        heapq.heappush(forward_heap, (forward_dist[v], v))
                if forward_dist[end] != float('inf'):
                    break

            # Expand reverse search
            while reverse_heap:
                d, u = heapq.heappop(reverse_heap)
                if visited[u]:
                    continue
                visited[u] = True
                for v, w in adj:
                    # Reverse the edge (v -> u)
                    # So we check for edges where u is the destination
                    # To reverse edges, we iterate through all edges
                    # and check if the edge points to u, then treat it as v -> u
                    for edge in edges:
                        if edge[1] == u:
                            rev_v = edge[0]
                            rev_w = edge[2]
                            if reverse_dist[rev_v] > d + rev_w:
                                reverse_dist[rev_v] = d + rev_w
                                heapq.heappush(reverse_heap, (reverse_dist[rev_v], rev_v))
                if reverse_dist[start] != float('inf'):
                    break

            # Check for meeting point
            if forward_dist[end] != float('inf') or reverse_dist[start] != float('inf'):
                if forward_dist[end] != float('inf'):
                    best = min(best, forward_dist[end])
                if reverse_dist[start] != float('inf'):
                    best = min(best, reverse_dist[start])

        return best if best != float('inf') else -1

    return bidirectional_dijkstra(s, t)
```

