import heapq

def solve(n, edges, s, t):
    from collections import defaultdict

    # Build adjacency list
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))

    # Function to perform Dijkstra from a start node
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        prev = [-1] * n  # To reconstruct path if needed

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u == end:
                break
            if current_dist > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    prev[v] = u
                    heapq.heappush(heap, (dist[v], v))
        return dist[end], prev

    # Bidirectional Dijkstra
    dist_s, _ = dijkstra(s, t)
    dist_t, _ = dijkstra(t, s)

    # Check if either direction has found the path
    if dist_s != float('inf') or dist_t != float('inf'):
        # Try to find the shortest path by combining both directions
        # We can use the reverse graph for the other direction
        reverse_adj = defaultdict(list)
        for u, v, w in edges:
            reverse_adj[v].append((u, w))

        def dijkstra_rev(start, end):
            dist = [float('inf')] * n
            dist[start] = 0
            heap = [(0, start)]
            prev = [-1] * n

            while heap:
                current_dist, u = heapq.heappop(heap)
                if u == end:
                    break
                if current_dist > dist[u]:
                    continue
                for v, w in reverse_adj[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w
                        prev[v] = u
                        heapq.heappush(heap, (dist[v], v))
            return dist[end], prev

        # Run Dijkstra from s to t and t to s (reversed)
        dist_s, _ = dijkstra(s, t)
        dist_t, _ = dijkstra_rev(t, s)

        # If both found, the minimal distance is the minimum of the two
        if dist_s != float('inf') and dist_t != float('inf'):
            return min(dist_s, dist_t)
        elif dist_s != float('inf'):
            return dist_s
        elif dist_t != float('inf'):
            return dist_t
        else:
            return -1
    else:
        return -1
