```python
import heapq

def solve(n, edges, s, t):
    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bidirectional Dijkstra
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        prev = [-1] * n

        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                break
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    prev[v] = u
                    heapq.heappush(heap, (dist[v], v))
        # Reconstruct path and return distance if found
        if dist[end] == float('inf'):
            return -1
        return dist[end]

    # Run Dijkstra from both ends
    distance = dijkstra(s, t)
    if distance != -1:
        return distance
    else:
        return dijkstra(t, s)
