from collections import deque

def solve(n, edges, s, t):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm from source
    def dijkstra(start, adj, n):
        dist = [float('inf')] * n
        dist[start] = 0
        pq = [(0, start)]
        while pq:
            d, u = pq.pop(0)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    pq.append((dist[v], v))
        return dist

    # Dijkstra's algorithm on reversed graph from target
    def dijkstra_reversed(start, adj_reversed, n):
        dist = [float('inf')] * n
        dist[start] = 0
        pq = [(0, start)]
        while pq:
            d, u = pq.pop(0)
            if d > dist[u]:
                continue
            for v, w in adj_reversed[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    pq.append((dist[v], v))
        return dist

    # Build reversed adjacency list
    adj_reversed = [[] for _ in range(n)]
    for u, v, w in edges:
        adj_reversed[v].append((u, w))

    # Run Dijkstra from source and from target on reversed graph
    dist_source = dijkstra(s, adj, n)
    dist_target = dijkstra_reversed(t, adj_reversed, n)

    # Find the shortest path using the combined distances
    min_distance = float('inf')
    for i in range(n):
        if dist_source[i] + dist_target[i] < min_distance:
            min_distance = dist_source[i] + dist_target[i]

    return min_distance if min_distance != float('inf') else -1
