from collections import deque

def solve(n, edges, s, t):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Initialize buckets: bucket[d] contains nodes with tentative distance d
    # We'll use a dictionary to keep track of bucket indices
    buckets = {}
    distance = [-1] * n
    distance[s] = 0
    buckets[0] = [s]

    # Use a deque for BFS-like processing
    queue = deque([0])

    while queue:
        d = queue.popleft()
        if d not in buckets:
            continue
        for node in buckets[d]:
            for neighbor, weight in adj[node]:
                if distance[neighbor] == -1 or distance[neighbor] > distance[node] + weight:
                    distance[neighbor] = distance[node] + weight
                    if distance[neighbor] not in buckets:
                        buckets[distance[neighbor]] = []
                    buckets[distance[neighbor]].append(neighbor)
                    queue.append(distance[neighbor])

    return distance[t] if distance[t] != -1 else -1
