def solve(n, edges, s, t):
    # Build adjacency lists for forward and reverse graphs
    forward = [[] for _ in range(n)]
    reverse = [[] for _ in range(n)]
    for u, v, w in edges:
        forward[u].append((v, w))
        reverse[v].append((u, w))  # reversed edge for backward search

    # Dijkstra's algorithm with priority queue
    def dijkstra(graph, start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                return d
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')

    # Perform alternating Dijkstra's search
    dist_forward = dijkstra(forward, s, t)
    dist_reverse = dijkstra(reverse, t, s)

    # If both paths are found, the shortest is the minimum of the two
    if dist_forward < float('inf'):
        return dist_forward
    if dist_reverse < float('inf'):
        return dist_reverse
    return -1
