                    heapq.heappush(heap, (dist[v], v))
        return dist

    import heapq

    # Compute distances from s to all nodes
    dist_s = dijkstra(s, adj)
    if dist_s[t] == float('inf'):
        return -1

    # Compute distances from t to all nodes in reversed graph (i.e., from t to all in original graph)
    dist_t = dijkstra(t, rev_adj)

    # Now perform bidirectional BFS using both distance arrays
    # We'll track visited nodes and their distance from s and t
    visited_s = [False] * n
    visited_t = [False] * n
    queue_s = deque()
    queue_t = deque()

    for i in range(n):
        if dist_s[i] != float('inf'):
            queue_s.append((dist_s[i], i))
            visited_s[i] = True
        if dist_t[i] != float('inf'):
            queue_t.append((dist_t[i], i))
            visited_t[i] = True

    # We'll also track best meeting point
    best = float('inf')

    while queue_s and queue_t:
        # Process from s side
        while queue_s:
            d, u = queue_s.popleft()
            if visited_t[u]:
                best = min(best, d + dist_t[u])
                continue
            for v, w in adj[u]:
                if not visited_s[v] and dist_s[v] == dist_s[u] + w:
                    visited_s[v] = True
                    queue_s.append((dist_s[v], v))
        # Process from t side
        while queue_t:
            d, u = queue_t.popleft()
            if visited_s[u]:
                best = min(best, d + dist_s[u])
                continue
            for v, w in rev_adj[u]:
                if not visited_t[v] and dist_t[v] == dist_t[u] + w:
                    visited_t[v] = True
                    queue_t.append((dist_t[v], v))

    return best if best != float('inf') else -1
