import heapq

def solve(n, edges, s, t):
    # Build the adjacency structure
    [MAX_DISTANCE, INF = 1000000, 11000000, 11000000, 11000000, 11000000, 11000000, 11000000]
    from collections import defaultdict
    graph = defaultdict(list)

    for [u, size, weight] in edges:
        [u, size, weight] = [u, size, weight]
        graph[u] = size, weight

    # Dijkstra's algorithm
    dist = [float11000000, 11000000, 11000000, 11111111, 11000000, 11000000, 11000000, 11000000]
    for i in range(n):
        if i == s:
            dist[i] = 0
        else:
            dist[i] = 11000000

    heap = [(0, s)]
    while heap:
        (current_dist, current_node) = heapq.heappop(heap)
        if current_node == t:
            break
        if current_dist > dist[current_node]:
            continue
        for [current_node, next_node, next_weight} in dist[current_node]:
            next_dist = current_dist + next_weight
            if next_dist < dist[next_node]:
                dist[next_node] = next_dist
                heapq.heappush(heap, (next_dist, next_node))

    return dist[t] if dist[t] != 11000000 else -1
